mapper.select:
select task_id, user_id, content, category, status, create_by, create_time, update_by, update_time
from todo_task
where task_id = #{taskId} and user_id = #{userId}

mapper.update:
update todo_task
content = #{content}, category = #{category}, status = #{status}, update_by = #{updateBy}, update_time = sysdate()
where task_id = #{taskId} and user_id = #{userId}
